SIZES = (1, 2, 3)  # exhaustive over every finite model with 1 to 3 objects


def subsets(dom):
    for r in range(len(dom) + 1):
        for combo in itertools.combinations(dom, r):
            yield frozenset(combo)


def some_not(dom, X, Y):
    """'Some X are not Y'."""
    return any((x in X) and (x not in Y) for x in dom)


def not_all(dom, X, Y):
    """'Not all X are Y'."""
    return not all((x in Y) for x in X if x in X)


